/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-tooltip {
  box-sizing: border-box;
  min-width: 0;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-body-size, 14px);
  font-weight: var(--ui-type-body-weight, 400);
  line-height: var(--ui-type-body-line-height, 1.6);
  letter-spacing: var(--ui-type-body-letter-spacing, 0em);
  color: var(--ui-text, #171717);
  overflow-wrap: anywhere;
}

:where([data-moru-registry]) .ui-tooltip-positioner {
  z-index: 90;
}

:where([data-moru-registry]) .ui-tooltip {
  max-width: min(calc(100vw - 24px), var(--available-width, calc(100vw - 24px)));
  max-height: min(calc(100dvh - 24px), var(--available-height, calc(100dvh - 24px)));
  overflow-y: auto;
  overscroll-behavior: contain;
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: calc(var(--ui-radius, 6px) + 4px);
  background: var(--ui-surface, #fff);
  box-shadow: var(--ui-shadow, 0 8px 28px #00000016);
  transform-origin: var(--transform-origin);
  transition:
    opacity var(--ui-duration, 160ms),
    transform var(--ui-duration, 160ms);
}

:where([data-moru-registry]) .ui-tooltip {
  width: max-content;
  max-width: min(280px, calc(100vw - 24px), var(--available-width, calc(100vw - 24px)));
  padding: var(--ui-field-gap, 8px) var(--ui-control-padding-x-sm, 10px);
  font-size: var(--ui-type-caption-size, 12px);
  font-weight: var(--ui-type-caption-weight, 400);
  line-height: var(--ui-type-caption-line-height, 1.5);
  letter-spacing: var(--ui-type-caption-letter-spacing, 0em);
  border-color: transparent;
  border-radius: var(--ui-radius, 6px);
  background: var(--ui-primary, #181818);
  color: var(--ui-primary-foreground, #fff);
}

:where([data-moru-registry]) .ui-tooltip[data-starting-style],
:where([data-moru-registry]) .ui-tooltip[data-ending-style] {
  opacity: 0;
  transform: scale(0.97);
}

:where([data-moru-registry]) .ui-tooltip[data-instant] {
  transition-duration: 0ms;
}

@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-tooltip {
    transition: none;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import {
  createContext,
  useContext,
  useId,
  useState,
  type ComponentPropsWithoutRef,
  type ReactElement,
  type ReactNode,
} from 'react'
import { Tooltip as BaseTooltip } from '@base-ui/react/tooltip'
import { cn } from './_lib/cn'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'
import './tooltip.css'

const TooltipProviderContext = createContext(false)

export interface TooltipProviderProps {
  children: ReactNode
  delay?: number
  closeDelay?: number
  timeout?: number
}

/** Group nearby tooltips to share the opening delay after the first tooltip. */
export function TooltipProvider({
  children,
  delay = 400,
  closeDelay = 100,
  timeout = 400,
}: TooltipProviderProps) {
  return (
    <TooltipProviderContext.Provider value={true}>
      <BaseTooltip.Provider delay={delay} closeDelay={closeDelay} timeout={timeout}>
        {children}
      </BaseTooltip.Provider>
    </TooltipProviderContext.Provider>
  )
}

export interface TooltipProps {
  trigger: ReactElement
  children: ReactNode
  side?: ComponentPropsWithoutRef<typeof BaseTooltip.Positioner>['side']
  align?: ComponentPropsWithoutRef<typeof BaseTooltip.Positioner>['align']
  className?: string
  delay?: number
}

export function Tooltip({
  trigger,
  children,
  side = 'top',
  align = 'center',
  className,
  delay,
}: TooltipProps) {
  const portalContainer = useThemePortalContainer()
  const hasProvider = useContext(TooltipProviderContext)
  const tooltipId = useId()
  const [open, setOpen] = useState(false)
  const existingDescription = (trigger.props as { 'aria-describedby'?: string })['aria-describedby']
  const describedBy =
    [existingDescription, open ? tooltipId : undefined].filter(Boolean).join(' ') || undefined
  const tooltip = (
    <BaseTooltip.Root open={open} onOpenChange={setOpen}>
      <BaseTooltip.Trigger render={trigger} delay={delay} aria-describedby={describedBy} />
      <OverlayPortal portal={BaseTooltip.Portal} kind="tooltip" container={portalContainer}>
        <BaseTooltip.Positioner
          className="ui-tooltip-positioner"
          side={side}
          align={align}
          sideOffset={8}
          collisionPadding={12}
          collisionAvoidance={{ side: 'flip', align: 'shift', fallbackAxisSide: 'end' }}
        >
          <BaseTooltip.Popup id={tooltipId} role="tooltip" className={cn('ui-tooltip', className)}>
            {children}
          </BaseTooltip.Popup>
        </BaseTooltip.Positioner>
      </OverlayPortal>
    </BaseTooltip.Root>
  )

  return hasProvider ? tooltip : <TooltipProvider>{tooltip}</TooltipProvider>
}
